const originals=new WeakMap();let observer;
function translate(){observer?.disconnect();const walk=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while((n=walk.nextNode())){if(['SCRIPT','STYLE','OPTION'].includes(n.parentElement?.tagName)&&n.parentElement.tagName!=='OPTION')continue;let saved=originals.get(n);if(!saved||n.nodeValue!==saved.last)saved={original:n.nodeValue,last:n.nodeValue};const next=t(saved.original);n.nodeValue=next;saved.last=next;originals.set(n,saved);}for(const e of document.querySelectorAll('[placeholder],[aria-label]'))for(const a of ['placeholder','aria-label'])if(e.hasAttribute(a)){const k='original'+a.replace('-','');if(!e.dataset[k])e.dataset[k]=e.getAttribute(a);e.setAttribute(a,t(e.dataset[k]));}document.documentElement.lang=language==='en'?'en':'zh-CN';observer?.observe(document.body,{childList:true,subtree:true,characterData:true});}
export function initLanguage(){const b=document.createElement('button');b.className='language-switch';b.setAttribute('aria-label','Switch language / 切换语言');b.textContent=language==='zh'?'EN':'中文';b.onclick=()=>{language=language==='zh'?'en':'zh';try{localStorage.setItem(KEY,language);}catch{}b.textContent=language==='zh'?'EN':'中文';window.dispatchEvent(new Event('languagechange'));translate();};document.querySelector('.top')?.append(b);observer=new MutationObserver(translate);translate();}
